insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000001','Spice Alley','Chippendale','Food & drink',array['Date night','Birthday dinner','Hidden gems']::text[],'Lanterns overhead, little kitchens all around. A casual laneway for choosing dinner together, one stall at a time.','Kensington Street, Chippendale NSW 2008',-33.8855,151.2015,'https://spice-alley.com.au/','Sydney','{"src":"photos/spice-alley.webp","smallSrc":"photos/spice-alley-480.webp","width":960,"height":1438,"alt":"Red lanterns above the narrow dining laneway at Spice Alley, Chippendale.","title":"Going home gnangarra-51.jpg","author":"Gnangarra","source":"https://commons.wikimedia.org/wiki/File:Going_home_gnangarra-51.jpg","license":"CC BY 2.5 au","licenseUrl":"https://creativecommons.org/licenses/by/2.5/au/deed.en","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000002','Opera Bar','Circular Quay','Bars',array['After-work drinks','Date night','Birthday dinner']::text[],'A drink beside the harbour, with the Opera House on one side and the bridge on the other. Plan ahead for busy evenings.','Lower Concourse, Sydney Opera House, Sydney NSW 2000',-33.8572,151.2142,'https://operabar.com.au/','Sydney','{"src":"photos/opera-bar.webp","smallSrc":"photos/opera-bar-480.webp","alt":"Tables and visitors at Opera Bar beside Sydney Harbour.","author":"Alex Proimos from Sydney, Australia","source":"https://commons.wikimedia.org/wiki/File%3AOpera%20Bar%20(3401033971).jpg","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000003','Royal Botanic Garden','Sydney','Outdoors',array['Weekend wandering','Family outings','Date night']::text[],'Take the long way through palms, garden paths and harbour lawns. Leave room in the afternoon for an unhurried picnic.','Mrs Macquaries Road, Sydney NSW 2000',-33.8642,151.2166,'https://www.botanicgardens.org.au/royal-botanic-garden-sydney','Sydney','{"src":"photos/botanic-garden.webp","smallSrc":"photos/botanic-garden-480.webp","width":960,"height":640,"alt":"Succulents and mature trees in the Royal Botanic Garden, Sydney.","title":"Sydney (AU), Royal Botanic Gardens -- 2019 -- 3079.jpg","author":"Dietmar Rabich","source":"https://commons.wikimedia.org/wiki/File:Sydney_(AU),_Royal_Botanic_Gardens_--_2019_--_3079.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000004','White Rabbit Gallery & Tea House','Chippendale','Cafes',array['Coffee dates','Hidden gems','Weekend wandering']::text[],'Contemporary Chinese art, then tea and a quiet conversation downstairs. The photograph shows the gallery exterior; check exhibition changeover dates.','30 Balfour Street, Chippendale NSW 2008',-33.8875,151.2006,'https://whiterabbitcollection.org/','Sydney','{"src":"photos/white-rabbit.webp","smallSrc":"photos/white-rabbit-480.webp","width":960,"height":720,"alt":"The brick exterior of White Rabbit Gallery in Chippendale.","title":"White Rabbit gallery December 2025.jpg","author":"Nick-D","source":"https://commons.wikimedia.org/wiki/File:White_Rabbit_gallery_December_2025.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000005','Circular Quay promenade','Circular Quay','Attractions',array['Weekend wandering','Family outings','Date night']::text[],'Ferries coming and going, a little sea air, and the city opening out around the water. A lovely meeting point before the rest of the day.','Circular Quay, Sydney NSW 2000',-33.8609,151.2121,'https://www.sydney.com/destinations/sydney/sydney-city/circular-quay','Sydney','{"src":"photos/quay-promenade.webp","smallSrc":"photos/quay-promenade-480.webp","width":960,"height":720,"alt":"People walking along Circular Quay promenade beside Sydney Cove.","title":"AUS Sydney, Central Business District, Circular Quay 012.jpg","author":"-wuppertaler","source":"https://commons.wikimedia.org/wiki/File:AUS_Sydney,_Central_Business_District,_Circular_Quay_012.jpg","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000006','Observatory Hill Park','The Rocks','Outdoors',array['Hidden gems','Date night','Weekend wandering']::text[],'A grassy hill, old trees and one of the city’s best bridge views. Bring a picnic rug and allow for uphill paths.','Upper Fort Street, Millers Point NSW 2000',-33.8596,151.2048,'https://www.cityofsydney.nsw.gov.au/parks/observatory-hill-park','Sydney','{"src":"photos/observatory-hill.webp","smallSrc":"photos/observatory-hill-480.webp","width":960,"height":540,"alt":"Sydney Harbour Bridge and the harbour seen from Observatory Hill.","title":"View from Observatory Hill, Sydney (483413) (9443070588).jpg","author":"Robert Linsdell from St. Andrews, Canada","source":"https://commons.wikimedia.org/wiki/File:View_from_Observatory_Hill,_Sydney_(483413)_(9443070588).jpg","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000007','Darling Square','Haymarket','Food & drink',array['Birthday dinner','Family outings','After-work drinks']::text[],'A whole neighbourhood of dining possibilities around The Exchange. Browse together, then choose a table that suits the group.','Steam Mill Lane, Haymarket NSW 2000',-33.8771,151.202,'https://www.darlingsq.com/','Sydney','{"src":"photos/darling-square.webp","smallSrc":"photos/darling-square-480.webp","width":960,"height":720,"alt":"The illuminated Exchange building and dining precinct at Darling Square.","title":"Darling Square Sydney.jpg","author":"MDRX","source":"https://commons.wikimedia.org/wiki/File:Darling_Square_Sydney.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000008','Art Gallery of New South Wales','Sydney','Art & culture',array['Weekend wandering','Family outings','Date night']::text[],'Let a favourite painting decide the pace. Explore the collection, the architecture and the paths towards the harbour.','Art Gallery Road, Sydney NSW 2000',-33.8688,151.2173,'https://www.artgallery.nsw.gov.au/','Sydney','{"src":"photos/art-gallery.webp","smallSrc":"photos/art-gallery-480.webp","width":960,"height":540,"alt":"The columned entrance to the Art Gallery of New South Wales.","title":"Sydney (AU), Art Gallery of New South Wales -- 2019 -- 3103.jpg","author":"Dietmar Rabich","source":"https://commons.wikimedia.org/wiki/File:Sydney_(AU),_Art_Gallery_of_New_South_Wales_--_2019_--_3103.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000009','Barangaroo Reserve','Barangaroo','Outdoors',array['Weekend wandering','Family outings','Hidden gems']::text[],'Sandstone edges, native planting and a waterfront walk made for slowing down. Bring water and sun protection.','Hickson Road, Barangaroo NSW 2000',-33.8587,151.2019,'https://www.barangaroo.com/see-and-do/barangaroo-reserve','Sydney','{"src":"photos/barangaroo-reserve.webp","smallSrc":"photos/barangaroo-reserve-480.webp","width":960,"height":720,"alt":"Grassy lawns, waterfront paths and trees at Barangaroo Reserve.","title":"AUS Sydney, Central Business District, Barangaroo Reserve 022.jpg","author":"-wuppertaler","source":"https://commons.wikimedia.org/wiki/File:AUS_Sydney,_Central_Business_District,_Barangaroo_Reserve_022.jpg","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000010','Chinese Garden of Friendship','Darling Harbour','Attractions',array['Date night','Hidden gems','Family outings']::text[],'Step away from the city into pavilions, winding paths and koi ponds. A small, thoughtful escape; admission charges apply.','Pier Street, Darling Harbour NSW 2000',-33.8764,151.2024,'https://www.darlingharbour.com/see-and-do/chinese-garden-of-friendship','Sydney','{"src":"photos/chinese-garden.webp","smallSrc":"photos/chinese-garden-480.webp","width":960,"height":720,"alt":"A pavilion, pond and rocks in the Chinese Garden of Friendship.","title":"2022-10-15 Chinese Garden of Friendship, Sydney 3.jpg","author":"Maksym Kozlenko","source":"https://commons.wikimedia.org/wiki/File:2022-10-15_Chinese_Garden_of_Friendship,_Sydney_3.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000011','Queen Victoria Building','Sydney','Shopping',array['Weekend wandering','Coffee dates','Places to try']::text[],'Look up at the clocks and stained glass before exploring the arcades. Make an afternoon of browsing and a tea stop.','455 George Street, Sydney NSW 2000',-33.8718,151.2067,'https://www.qvb.com.au/','Sydney','{"src":"photos/qvb.webp","smallSrc":"photos/qvb-480.webp","alt":"The ornate interior and Royal Clock of the Queen Victoria Building in Sydney.","author":"Kgbo","source":"https://commons.wikimedia.org/wiki/File%3AInterior%20of%20Queen%20Victoria%20Building%20with%20Royal%20Clock%2C%20Sydney%2002.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000012','Museum of Contemporary Art Australia','The Rocks','Art & culture',array['Date night','Weekend wandering','Coffee dates']::text[],'Harbourside contemporary art with plenty to talk about afterwards. Check current exhibition access and ticket conditions.','140 George Street, The Rocks NSW 2000',-33.8599,151.209,'https://www.mca.com.au/','Sydney','{"src":"photos/mca.webp","smallSrc":"photos/mca-480.webp","width":960,"height":540,"alt":"The sandstone facade of the Museum of Contemporary Art Australia.","title":"The Museum of Contemporary Art, Sydney (former MSB Building).jpg","author":"Briandhana Krishnatirta Kusaditya","source":"https://commons.wikimedia.org/wiki/File:The_Museum_of_Contemporary_Art,_Sydney_(former_MSB_Building).jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000013','Paddy’s Markets Haymarket','Haymarket','Shopping',array['Family outings','Weekend wandering','Hidden gems']::text[],'Browse the covered stalls for a small find or something unexpected. Trading days vary, so check before setting out.','9–13 Hay Street, Haymarket NSW 2000',-33.8792,151.2035,'https://paddysmarkets.com.au/','Sydney','{"src":"photos/paddys-markets.webp","smallSrc":"photos/paddys-markets-480.webp","width":960,"height":720,"alt":"The Market City entrance above Paddy''s Markets in Haymarket.","title":"Haymarket Market City entrance.JPG","author":"J Bar","source":"https://commons.wikimedia.org/wiki/File:Haymarket_Market_City_entrance.JPG","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000014','Hyde Park','Sydney','Outdoors',array['Weekend wandering','Family outings','Coffee dates']::text[],'A shady pause beneath the fig trees, right in the middle of town. Pair a slow walk with something from a nearby cafe.','Elizabeth Street, Sydney NSW 2000',-33.8731,151.2113,'https://www.cityofsydney.nsw.gov.au/parks/hyde-park','Sydney','{"src":"photos/hyde-park.webp","smallSrc":"photos/hyde-park-480.webp","width":960,"height":720,"alt":"A shaded, tree-lined path through Hyde Park in central Sydney.","title":"AUS Sydney, Central Business District, Hyde Park 020.jpg","author":"-wuppertaler","source":"https://commons.wikimedia.org/wiki/File:AUS_Sydney,_Central_Business_District,_Hyde_Park_020.jpg","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000015','State Library of New South Wales','Sydney','Art & culture',array['Hidden gems','Weekend wandering']::text[],'Reading rooms, sandstone and changing displays. An easy way to turn an ordinary lunch break into a little discovery.','1 Shakespeare Place, Sydney NSW 2000',-33.8662,151.2128,'https://www.sl.nsw.gov.au/','Sydney','{"src":"photos/state-library.webp","smallSrc":"photos/state-library-480.webp","width":960,"height":507,"alt":"The sandstone Mitchell and Dixson wings of the State Library of New South Wales.","title":"Mitchell and Dixson wings, State Library of New South Wales, 2023.jpg","author":"Geoff Barker","source":"https://commons.wikimedia.org/wiki/File:Mitchell_and_Dixson_wings,_State_Library_of_New_South_Wales,_2023.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
insert into public.somewhere_places (id,name,suburb,category,occasions,description,address,latitude,longitude,website,city,photo) values ('20000000-0000-4000-8000-000000000016','Pyrmont Bridge','Darling Harbour','Attractions',array['Weekend wandering','Family outings','Date night']::text[],'Walk across the harbour on a historic swing bridge. Come back after dark to see the waterfront in a different light.','Pyrmont Bridge, Darling Harbour NSW 2000',-33.8705,151.2013,'https://www.darlingharbour.com/see-and-do/pyrmont-bridge','Sydney','{"src":"photos/pyrmont-bridge.webp","smallSrc":"photos/pyrmont-bridge-480.webp","width":960,"height":720,"alt":"The pedestrian Pyrmont Bridge crossing Darling Harbour.","title":"Pyrmont Bridge February 2014.jpg","author":"Nick-D","source":"https://commons.wikimedia.org/wiki/File:Pyrmont_Bridge_February_2014.jpg","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","modifications":"Resized and WebP-compressed; cropped to fit in the interface."}'::jsonb) on conflict do nothing;
